func (svc node) Update(ctx, upd *types.Node) (*types.Node, error) {
  return svc.updater(ctx, upd.ID, NodeActionUpdate, func(ctx, n *types.Node) error {
    n.Name = upd.Name; n.BaseURL = upd.BaseURL; n.Contact = upd.Contact
    n.UpdatedBy = auth.GetIdentityFromContext(ctx).Identity()
    n.UpdatedAt = now()
    return nil
  }, nil)
}

func (svc node) DeleteByID(ctx, ID uint64) error {
  _, err := svc.updater(ctx, ID, NodeActionDelete, func(ctx, n *types.Node) error {
    n.DeletedAt = now(); n.DeletedBy = auth.GetIdentityFromContext(ctx).Identity()
    return nil
  }, nil)
  return err
}

func (svc node) UndeleteByID(ctx, ID uint64) error {
