    n.DeletedAt = nil; n.DeletedBy = 0
    return nil
  }, nil)
  return err
}

func (svc exposedModule) Find(ctx, filter ExposedModuleFilter) (set, f, err) {
  filter.Check = func(res *ExposedModule) (bool, error) {
    if !svc.ac.CanManageExposedModule(ctx, res) { return false, ExposedModuleErrNotAllowedToManage() }
    return true, nil
  }
  set, f, err = store.SearchFederationExposedModules(ctx, svc.store, filter)
  return set, f, err
}

