}

func (svc moduleMapping) Find(ctx, filter ModuleMappingFilter) (set, f, err) {
  filter.Check = func(res *ModuleMapping) (bool, error) {
    sm, err := svc.smodule.FindByID(ctx, res.NodeID, res.FederationModuleID); if err != nil { return false, err }
    if !svc.ac.CanMapSharedModule(ctx, sm) { return false, ModuleMappingErrNotAllowedToMap() }
    return true, nil
  }
  set, f, err = store.SearchFederationModuleMappings(ctx, svc.store, filter)
  set.Walk(func(mm){ mm.NodeID = f.NodeID })
  return set, f, err
}

